// models/Follow.js
const mongoose = require('mongoose');
const followSchema = new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
  actor: { type: mongoose.Schema.Types.ObjectId, ref: 'Actor', required: true, index: true },
}, { timestamps: true });
followSchema.index({ user: 1, actor: 1 }, { unique: true });
module.exports = mongoose.model('Follow', followSchema);

// models/Notification.js
// (same mongoose import as above)
const notificationSchema = new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
  movie: { type: mongoose.Schema.Types.ObjectId, ref: 'Movie' },
  message: String,
  read: { type: Boolean, default: false },
}, { timestamps: true });
notificationSchema.index({ user: 1, read: 1 });
notificationSchema.index({ user: 1, createdAt: -1 });
module.exports = mongoose.model('Notification', notificationSchema);

// routes/social.js
// (separate file; mongoose is required the same way as in the model above)
const express = require('express');
const Follow = require('../models/Follow');
const Notification = require('../models/Notification');
const Movie = require('../models/Movie');
const Actor = require('../models/Actor');
const { requireAuth, requireAdmin } = require('../middleware/auth');

const router = express.Router();
router.use(requireAuth);
const valid = (id) => mongoose.Types.ObjectId.isValid(id);

router.post('/follow', async (req, res, next) => {
  const { actorId } = req.body;
  if (!valid(actorId)) return res.status(400).json({ message: 'Invalid actor id' });
  try {
    if (!(await Actor.exists({ _id: actorId }))) return res.status(404).json({ message: 'Actor not found' });
    await Follow.create({ user: req.user.id, actor: actorId });
    res.status(201).json({ message: 'Following' });
  } catch (e) {
    if (e.code === 11000) return res.status(409).json({ message: 'Already following' });
    next(e);
  }
});

router.get('/notifications', async (req, res, next) => {
  const page = Math.max(1, parseInt(req.query.page, 10) || 1);
  const limit = Math.min(50, Math.max(1, parseInt(req.query.limit, 10) || 20));
  try {
    const filter = { user: req.user.id };
    const [items, total] = await Promise.all([
      Notification.find(filter).sort({ createdAt: -1 }).skip((page - 1) * limit).limit(limit).populate('movie', 'title'),
      Notification.countDocuments(filter),
    ]);
    res.json({ items, page, limit, total });
  } catch (e) { next(e); }
});

router.get('/notifications/unread-count', async (req, res, next) => {
  try { res.json({ count: await Notification.countDocuments({ user: req.user.id, read: false }) }); }
  catch (e) { next(e); }
});

router.put('/notifications/:id/read', async (req, res, next) => {
  if (!valid(req.params.id)) return res.status(404).json({ message: 'Notification not found' });
  try {
    const r = await Notification.updateOne({ _id: req.params.id, user: req.user.id }, { read: true });
    if (!r.matchedCount) return res.status(404).json({ message: 'Notification not found' });
    res.json({ message: 'Marked as read' });
  } catch (e) { next(e); }
});

router.post('/admin/movies', requireAdmin, async (req, res, next) => {
  try { res.status(201).json(await Movie.create({ ...req.body, launched: false })); }
  catch (e) { next(e); }
});

router.post('/admin/movies/:id/launch', requireAdmin, async (req, res, next) => {
  if (!valid(req.params.id)) return res.status(400).json({ message: 'Invalid movie id' });
  try {
    const movie = await Movie.findOneAndUpdate(
      { _id: req.params.id, launched: false }, { launched: true }, { new: true },
    );
    if (!movie) {
      const exists = await Movie.exists({ _id: req.params.id });
      return res.status(exists ? 409 : 404).json({ message: exists ? 'Movie already launched' : 'Movie not found' });
    }
    const followers = await Follow.distinct('user', { actor: { $in: movie.cast } });
    const BATCH = 1000;
    for (let i = 0; i < followers.length; i += BATCH) {
      await Notification.insertMany(
        followers.slice(i, i + BATCH).map((user) => ({
          user, movie: movie._id, message: `New release: ${movie.title}`,
        })),
        { ordered: false },
      );
    }
    res.json({ message: 'Movie launched', notified: followers.length });
  } catch (e) { next(e); }
});

module.exports = router;
